<?php $page_title='รายการโปรด';require_once __DIR__.'/includes/auth_check.php';requireLogin();require_once __DIR__.'/config/database.php';$db=(new Database())->getConnection();$stmt=$db->prepare("SELECT p.*,c.name category_name FROM wishlists w JOIN products p ON p.id=w.product_id LEFT JOIN categories c ON c.id=p.category_id WHERE w.user_id=? AND p.approval_status='approved' ORDER BY w.created_at DESC");$stmt->execute([(int)$_SESSION['user_id']]);$products=$stmt->fetchAll();require_once __DIR__.'/includes/header.php';?><div class="container" style="margin:36px auto 70px"><div class="section-header"><div><p class="eyebrow">SAVED ITEMS</p><h1>รายการโปรดของฉัน</h1></div></div><div class="product-grid"><?php if(!$products):?><section class="checkout-card" style="grid-column:1/-1;text-align:center">ยังไม่มีสินค้าในรายการโปรด</section><?php endif;?><?php foreach($products as $p):?><article class="product-card"><a href="<?php echo BASE_URL;?>product-detail.php?id=<?php echo (int)$p['id'];?>"><div class="product-image"><img src="<?php echo e(productImageUrl($p['image_url']));?>" alt="<?php echo e($p['name']);?>"></div><div class="product-info"><small><?php echo e($p['category_name']);?></small><h3><?php echo e($p['name']);?></h3><strong><?php echo formatCurrency($p['price']);?></strong></div></a><button class="btn btn-primary" onclick="addToCart(<?php echo (int)$p['id'];?>,1)">เพิ่มลงตะกร้า</button></article><?php endforeach;?></div></div><?php require_once __DIR__.'/includes/footer.php';?>
